public class UndocumentedMethodCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String widget = "public class Widget {\n"
                + "    public int size;\n"
                + "\n"
                + "    /** Makes a widget. */\n"
                + "    public Widget(int size) { this.size = size; }\n"
                + "\n"
                + "    /*\n"
                + "     * Not a doc comment.\n"
                + "     */\n"
                + "    public int area() { return size * size; }\n"
                + "\n"
                + "    public void reset() { size = 0; }\n"
                + "\n"
                + "    /**\n"
                + "     * Grows the widget.\n"
                + "     */\n"
                + "    public void grow(int amount) { size += amount; }\n"
                + "\n"
                + "    private void secret() { }\n"
                + "}\n";
        String tidy = "public class Tidy {\n"
                + "    /**\n"
                + "     * Answers.\n"
                + "     */\n"
                + "    public int answer() { return 42; }\n"
                + "}\n";
        String naked = "public int lonely() { return 1; }\n";

        check("undocumented members in order", "[area, reset]",
                UndocumentedMethodCounter.undocumentedMembers(widget).toString());
        check("count of undocumented", 2, UndocumentedMethodCounter.countUndocumented(widget));
        check("constructor with one line doc counts as documented", false,
                UndocumentedMethodCounter.undocumentedMembers(widget).contains("Widget"));
        check("private members ignored", false,
                UndocumentedMethodCounter.undocumentedMembers(widget).contains("secret"));
        check("fully documented class", "[]",
                UndocumentedMethodCounter.undocumentedMembers(tidy).toString());
        check("member on the first line", "[lonely]",
                UndocumentedMethodCounter.undocumentedMembers(naked).toString());
        check("count with nothing above", 1, UndocumentedMethodCounter.countUndocumented(naked));
        check("null source", "[]", UndocumentedMethodCounter.undocumentedMembers(null).toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

