public class UndocumentedMethodCounter {

    public static java.util.List<String> undocumentedMembers(String source) {
        java.util.List<String> names = new java.util.ArrayList<>();
        if (source == null) {
            return names;
        }
        String[] lines = source.split("\n", -1);
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i].trim();
            if (!line.startsWith("public ") || !line.contains("(")) {
                continue;
            }
            if (documented(lines, i)) {
                continue;
            }
            names.add(nameOf(line));
        }
        return names;
    }

    public static int countUndocumented(String source) {
        return undocumentedMembers(source).size();
    }

    private static String nameOf(String memberLine) {
        String head = memberLine.substring(0, memberLine.indexOf('(')).trim();
        String[] words = head.split("\\s+");
        return words[words.length - 1];
    }

    private static boolean documented(String[] lines, int memberIndex) {
        int i = memberIndex - 1;
        while (i >= 0 && lines[i].trim().isEmpty()) {
            i--;
        }
        if (i < 0 || !lines[i].trim().endsWith("*/")) {
            return false;
        }
        while (i >= 0) {
            String line = lines[i].trim();
            if (line.startsWith("/**")) {
                return true;
            }
            if (line.startsWith("/*")) {
                return false;
            }
            i--;
        }
        return false;
    }
}
